/*
A: ℝ^(n×n)
        a = A_1,1
        n: ℤ
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT a;

    heartlib(
        const Eigen::MatrixXd & A,
        const int & n)
    {
        assert( A.rows() == n );
        assert( A.cols() == n );
        // a = A_1,1
        a = A(1-1, 1-1);
    }
};

